import csv, json
from decimal import Decimal, ROUND_HALF_UP
from datetime import date

fees = json.load(open('inputs/fees.json'))
merchants = {m['merchant']: m for m in json.load(open('inputs/merchant_data.json'))}

# ---------- Q1464: fee IDs applicable to account_type=R and aci=B ----------
q1464 = [r['ID'] for r in fees
         if (not r['account_type'] or 'R' in r['account_type'])
         and (not r['aci'] or 'B' in r['aci'])]
q1464.sort()

# ---------- aggregate Belles transactions by month ----------
belles = merchants['Belles_cookbook_store']
vol = {}          # month -> Decimal volume
fraud_vol = {}    # month -> Decimal fraudulent volume
belles_rows = []  # (row, month)
with open('inputs/payments.csv', newline='') as fh:
    for row in csv.DictReader(fh):
        if row['merchant'] != 'Belles_cookbook_store':
            continue
        doy = int(row['day_of_year'])
        mon = date.fromordinal(date(2023, 1, 1).toordinal() + doy - 1).month
        amt = Decimal(row['eur_amount'])
        vol[mon] = vol.get(mon, Decimal(0)) + amt
        if row['has_fraudulent_dispute'] == 'True':
            fraud_vol[mon] = fraud_vol.get(mon, Decimal(0)) + amt
        belles_rows.append((row, mon, doy))

def volume_band(v):
    if v < Decimal('100000'):
        return '<100k'
    if v < Decimal('1000000'):
        return '100k-1m'
    if v < Decimal('5000000'):
        return '1m-5m'
    return '>5m'

def fraud_band(ratio):
    p = ratio * 100
    if p < Decimal('7.2'):
        return '<7.2%'
    if p < Decimal('7.7'):
        return '7.2%-7.7%'
    if p <= Decimal('8.3'):
        return '7.7%-8.3%'
    return '>8.3%'

def capture_band(c):
    c = str(c)
    if c in ('1', '2'):
        return '<3'
    if c == '7':
        return '>5'
    return c  # immediate / manual

def merchant_rule_ids(month):
    fb = fraud_band(fraud_vol[month] / vol[month])
    vb = volume_band(vol[month])
    ids = []
    for r in fees:
        if r['account_type'] and belles['account_type'] not in r['account_type']:
            continue
        if r['capture_delay'] and r['capture_delay'] != capture_band(belles['capture_delay']):
            continue
        if r['monthly_fraud_level'] and r['monthly_fraud_level'] != fb:
            continue
        if r['monthly_volume'] and r['monthly_volume'] != vb:
            continue
        if r['merchant_category_code'] and belles['merchant_category_code'] not in r['merchant_category_code']:
            continue
        ids.append(r['ID'])
    return sorted(ids)

q1681 = merchant_rule_ids(1)   # 10 Jan 2023 -> January
q1753 = merchant_rule_ids(3)   # March 2023

# ---------- Q1871: delta if fee ID=384 rate changes to 1 ----------
rule384 = next(r for r in fees if r['ID'] == 384)
delta = Decimal(0)
for row, mon, doy in belles_rows:
    if mon != 1:
        continue
    if rule384['card_scheme'] and rule384['card_scheme'] != row['card_scheme']:
        continue
    if rule384['account_type'] and belles['account_type'] not in rule384['account_type']:
        continue
    if rule384['capture_delay'] and rule384['capture_delay'] != capture_band(belles['capture_delay']):
        continue
    if rule384['monthly_fraud_level'] and rule384['monthly_fraud_level'] != fraud_band(fraud_vol[mon] / vol[mon]):
        continue
    if rule384['monthly_volume'] and rule384['monthly_volume'] != volume_band(vol[mon]):
        continue
    if rule384['merchant_category_code'] and belles['merchant_category_code'] not in rule384['merchant_category_code']:
        continue
    if rule384['is_credit'] is not None and rule384['is_credit'] != (row['is_credit'] == 'True'):
        continue
    if rule384['aci'] and row['aci'] not in rule384['aci']:
        continue
    if rule384['intracountry'] is not None and bool(int(rule384['intracountry'])) != (row['issuing_country'] == row['acquirer_country']):
        continue
    amt = Decimal(row['eur_amount'])
    delta += (Decimal(1) - Decimal(rule384['rate'])) * amt / Decimal(10000)
q1871 = delta.quantize(Decimal('0.00000000000001'), rounding=ROUND_HALF_UP)

# ---------- Q2697: cheapest fee per fraudulent transaction for each ACI ----------
fraud_rows = [(row, mon) for row, mon, doy in belles_rows
              if mon == 1 and row['has_fraudulent_dispute'] == 'True']
def applicable(row, mon, aci):
    out = []
    fb = fraud_band(fraud_vol[mon] / vol[mon])
    vb = volume_band(vol[mon])
    for r in fees:
        if r['card_scheme'] and r['card_scheme'] != row['card_scheme']:
            continue
        if r['account_type'] and belles['account_type'] not in r['account_type']:
            continue
        if r['capture_delay'] and r['capture_delay'] != capture_band(belles['capture_delay']):
            continue
        if r['monthly_fraud_level'] and r['monthly_fraud_level'] != fb:
            continue
        if r['monthly_volume'] and r['monthly_volume'] != vb:
            continue
        if r['merchant_category_code'] and belles['merchant_category_code'] not in r['merchant_category_code']:
            continue
        if r['is_credit'] is not None and r['is_credit'] != (row['is_credit'] == 'True'):
            continue
        if r['aci'] and aci not in r['aci']:
            continue
        if r['intracountry'] is not None and bool(int(r['intracountry'])) != (row['issuing_country'] == row['acquirer_country']):
            continue
        out.append(r)
    return out
costs = {}
for aci in 'ABCDEFG':
    total = Decimal(0)
    for row, mon in fraud_rows:
        rs = applicable(row, mon, aci)
        if not rs:
            continue
        amt = Decimal(row['eur_amount'])
        fs = [Decimal(str(r['fixed_amount'])) + Decimal(r['rate']) * amt / Decimal(10000) for r in rs]
        total += min(fs)
    costs[aci] = total
best_aci = min('ABCDEFG', key=lambda a: (costs[a], a))
q2697 = f"{best_aci}:{costs[best_aci].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}"
print('costs', {k: str(v) for k,v in costs.items()})
print('best', q2697)

# ---------- Q1273 / Q1305 averages ----------
def fee10(r):
    return Decimal(str(r['fixed_amount'])) + Decimal(r['rate']) * Decimal(10) / Decimal(10000)
def avg(rs):
    return sum((fee10(r) for r in rs), Decimal(0)) / Decimal(len(rs))
rs1273 = [r for r in fees if r['card_scheme'] == 'GlobalCard'
          and (r['is_credit'] is True or r['is_credit'] is None)]
q1273 = avg(rs1273).quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)
rs1305 = [r for r in fees if r['card_scheme'] == 'GlobalCard'
          and (not r['account_type'] or 'H' in r['account_type'])
          and (not r['merchant_category_code'] or 5812 in r['merchant_category_code'])]
q1305 = avg(rs1305).quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)
print('q1273', q1273, 'n', len(rs1273))
print('q1305', q1305, 'n', len(rs1305))
print('q1464 count', len(q1464))
print('q1681 count', len(q1681), q1681)
print('q1753 count', len(q1753), q1753)
print('q1871', q1871)

answers = {
    '5': 'NL',
    '49': 'A. NL',
    '70': 'yes',
    '1273': str(q1273),
    '1305': str(q1305),
    '1464': ', '.join(map(str, q1464)),
    '1681': ', '.join(map(str, q1681)),
    '1753': ', '.join(map(str, q1753)),
    '1871': f"{q1871:.14f}",
    '2697': q2697,
}
with open('answers.jsonl', 'w', encoding='utf-8') as out:
    for q in ['5','49','70','1273','1305','1464','1681','1753','1871','2697']:
        out.write(json.dumps({'task_id': q, 'answer': answers[q]}, ensure_ascii=False) + '\n')
print('written')
